const FOOT = { house: [1.6, 1.4, 0.7], tent: [1.1, 1.1, 0.45], crate: [0.9, 0.5, 0.4], pillar: [0.55, 0.55, 0.6], arch: [2, 0.4, 0.6] }, built = [];
const settle = (type, it) => {
